#!/usr/bin/env bash
set -Eeuo pipefail

STAGE_VERSION="rnatr_general_repeat_caller_boundary_censor_denovo_v0.3.0"
PROJECT_ROOT="/mnt/intelssd/rnatr_project"
SRC_DIR="$PROJECT_ROOT/src/rnatr_scout/general_caller"
CALLER_V02="$SRC_DIR/rnatr_general_repeat_caller_ref_v0.2.0.py"
CALLER="$SRC_DIR/rnatr_general_repeat_caller_ref_v0.3.0.py"
SCRIPT_DIR="$PROJECT_ROOT/scripts"
SELFTEST="$SCRIPT_DIR/rnatr_general_repeat_caller_boundary_censor_denovo_selftest_v0.3.0.py"
SELFTEST_V01="$PROJECT_ROOT/benchmarks/general_repeat_caller/v0.1.0/rnatr_general_repeat_caller_fixture_selftest_v0.1.0.py"
SELFTEST_V02="$SCRIPT_DIR/rnatr_general_repeat_caller_fixture_selftest_v0.2.0.py"
FIXTURES_REAL="$PROJECT_ROOT/benchmarks/general_repeat_caller/v0.2.0/real_p01_regression_materialized.tsv"
CALLS_V02="$PROJECT_ROOT/benchmarks/general_repeat_caller/v0.2.0/real_p01_regression_calls.v0.2.0.tsv"
AUDIT12C="$PROJECT_ROOT/qc/12_general_repeat_caller_real_regression_audit/v0.2.0/general_repeat_caller_real_regression_audit.qc.tsv"
QC12B="$PROJECT_ROOT/qc/12_general_repeat_caller_compound_lps/v0.2.0/general_repeat_caller_stage12b.qc.tsv"
BENCH="$PROJECT_ROOT/benchmarks/general_repeat_caller/v0.3.0"
QC_DIR="$PROJECT_ROOT/qc/12_general_repeat_caller_boundary_censor_denovo/v0.3.0"
STAGE_QC="$QC_DIR/general_repeat_caller_stage12d.qc.tsv"
NOTE="$PROJECT_ROOT/docs/design/RNA_TR_Scout_general_repeat_caller_reference_v0.3.0.md"
SSOT_CLI="$PROJECT_ROOT/metadata/ssot/rnatr_ssot.py"
SSOT_DB="$PROJECT_ROOT/metadata/ssot/rnatr_ssot.sqlite"
SCRIPT_INSTALL="$SCRIPT_DIR/12d_implement_boundary_censor_denovo_v0.3.1.sh"

for p in "$CALLER_V02" "$SELFTEST_V01" "$SELFTEST_V02" "$FIXTURES_REAL" "$CALLS_V02" "$AUDIT12C" "$QC12B" "$SSOT_CLI" "$SSOT_DB"; do
  [[ -s "$p" ]] || { echo "ERROR: required Stage 12D input missing: $p" >&2; exit 2; }
done

stage12b_status="$(awk -F '\t' '$1=="audit_status"{print $2}' "$QC12B" | tr -d '\015' | tail -n 1)"
stage12c_status="$(awk -F '\t' '$1=="audit_status"{print $2}' "$AUDIT12C" | tr -d '\015' | tail -n 1)"
[[ "$stage12b_status" == "PASS" ]] || { echo "ERROR: Stage 12B not PASS: $stage12b_status" >&2; exit 2; }
[[ "$stage12c_status" == "PASS" ]] || { echo "ERROR: Stage 12C not PASS: $stage12c_status" >&2; exit 2; }

if [[ -s "$STAGE_QC" ]] && awk -F '\t' '$1=="audit_status"{print $2}' "$STAGE_QC" | tr -d '\015' | grep -qx 'PASS'; then
  echo "STAGE12D_ALREADY_PASS"; cat "$STAGE_QC"; exit 0
fi

for d in "$BENCH" "$QC_DIR"; do
  [[ ! -e "$d" ]] || { echo "ERROR: existing incomplete Stage 12D output; refusing overwrite: $d" >&2; exit 2; }
done
mkdir -p "$BENCH" "$QC_DIR" "$SRC_DIR" "$SCRIPT_DIR" "$(dirname "$NOTE")"

created_caller=0; created_selftest=0; created_note=0
cleanup_fail() {
  rc=$?
  echo "ERROR: Stage 12D failed; cleaning new Stage 12D outputs" >&2
  [[ "$created_caller" == 1 ]] && rm -f "$CALLER"
  [[ "$created_selftest" == 1 ]] && rm -f "$SELFTEST"
  [[ "$created_note" == 1 ]] && rm -f "$NOTE"
  [[ "$BENCH" == "$PROJECT_ROOT/benchmarks/general_repeat_caller/v0.3.0" ]] && rm -rf "$BENCH"
  [[ "$QC_DIR" == "$PROJECT_ROOT/qc/12_general_repeat_caller_boundary_censor_denovo/v0.3.0" ]] && rm -rf "$QC_DIR"
  exit "$rc"
}
trap cleanup_fail ERR

install_payload() {
  local dest="$1" mode="$2" expected="$3" data="$4" flag="$5"
  local tmp="${dest}.stage12d.part"
  printf '%s' "$data" | base64 -d > "$tmp"
  local got; got="$(sha256sum "$tmp" | awk '{print $1}')"
  [[ "$got" == "$expected" ]] || { rm -f "$tmp"; echo "ERROR: payload SHA mismatch: $dest" >&2; exit 2; }
  if [[ -e "$dest" ]]; then
    local old; old="$(sha256sum "$dest" | awk '{print $1}')"
    [[ "$old" == "$expected" ]] || { rm -f "$tmp"; echo "ERROR: existing file differs: $dest" >&2; exit 2; }
    rm -f "$tmp"
  else
    chmod "$mode" "$tmp"; mv "$tmp" "$dest"; printf -v "$flag" '%s' 1
  fi
}

install_payload "$CALLER" 0755 "6f201a30562227384fb18067c56ecfc1b4859fc2ed65d119f07ae90184aec5b3" "" created_caller
install_payload "$SELFTEST" 0755 "99401e05b589f0604a542ed3a3dfc223e7bd6a2c9b86e4456cca17380a8de188" "" created_selftest
install_payload "$NOTE" 0644 "97ba92a53cea444da0c8b5f4f7c667fc6fec8806553a76e56941f0b2fb543382" "" created_note
python -m py_compile "$CALLER" "$SELFTEST"

SELF="$(readlink -f "$0")"
if [[ "$SELF" != "$SCRIPT_INSTALL" && ! -e "$SCRIPT_INSTALL" ]]; then
  cp "$SELF" "$SCRIPT_INSTALL.part"; chmod 0755 "$SCRIPT_INSTALL.part"; mv "$SCRIPT_INSTALL.part" "$SCRIPT_INSTALL"
fi

echo "===== 12D SIMPLE PERIODIC REGRESSION ====="
python "$SELFTEST_V01" --caller "$CALLER" --outdir "$BENCH/simple_periodic"

echo "===== 12D COMPOUND / INTERRUPTION / LPS REGRESSION ====="
python "$SELFTEST_V02" --caller "$CALLER" --outdir "$BENCH/compound_interruption_lps"

echo "===== 12D BOUNDARY / CENSOR / DENOVO SELFTEST ====="
python "$SELFTEST" --caller "$CALLER" --outdir "$BENCH/boundary_censor_denovo"

echo "===== 12D REAL P0/P1 SOFTWARE REGRESSION ====="
python - "$CALLER" "$FIXTURES_REAL" "$CALLS_V02" "$BENCH/real_p01_regression_calls.v0.3.0.tsv" "$BENCH/real_p01_regression.qc.tsv" <<'PYREAL'
from __future__ import annotations
import csv,importlib.util,sys,statistics,math,os
from pathlib import Path

def load(path):
    spec=importlib.util.spec_from_file_location('rnatr_v030_real',path)
    mod=importlib.util.module_from_spec(spec);sys.modules[spec.name]=mod;spec.loader.exec_module(mod);return mod

def percentile(vals,q):
    s=sorted(float(x) for x in vals)
    if not s:return None
    if len(s)==1:return s[0]
    pos=(len(s)-1)*q; lo=math.floor(pos); hi=math.ceil(pos)
    return s[lo] if lo==hi else s[lo]*(hi-pos)+s[hi]*(pos-lo)

caller=load(Path(sys.argv[1])); fixtures=Path(sys.argv[2]); oldcalls=Path(sys.argv[3]); out=Path(sys.argv[4]); qc=Path(sys.argv[5])
with fixtures.open() as fh: rows=list(csv.DictReader(fh,delimiter='	'))
with oldcalls.open() as fh: old={r['projection_id']:r for r in csv.DictReader(fh,delimiter='	')}
if len(rows)!=60: raise SystemExit(f'ERROR: expected 60 real fixtures, got {len(rows)}')
res=[]; absd=[]; motifok=[]; overlaps=[]; context_limited=0; gt50=0; gt100=0; ext50=0
for r in rows:
    geom=r.get('evidence_class','SPAN') or 'SPAN'
    context='PROJECTION_WINDOW' if r.get('materialization_mode')=='PROJECTION_WINDOW_FASTQ' else 'FULL_READ'
    c=caller.call_repeat(r['sequence'],int(r['prior_start']),int(r['prior_end']),[r['canonical_motif']],evidence_geometry=geom,sequence_context=context)
    frozen=float(r['repeat_bp_estimate']); delta=float(c.repeat_bp_observed)-frozen; ad=abs(delta); absd.append(ad)
    truth=caller.canonical_motif(r['canonical_motif']); ok=c.canonical_motif==truth; motifok.append(ok); overlaps.append(c.prior_overlap_bp)
    context_limited+=int(c.context_limited); gt50+=int(ad>50); gt100+=int(ad>100)
    ext=max(0,int(c.left_extension_bp))+max(0,int(c.right_extension_bp)); ext50+=int(ext>50)
    d=c.__dict__.copy()
    res.append({'projection_id':r['projection_id'],'read_id':r['read_id'],'representative_locus_id':r.get('representative_locus_id',''),
                'frozen_canonical_motif':r['canonical_motif'],'frozen_repeat_bp_estimate':r['repeat_bp_estimate'],
                'new_canonical_motif':c.canonical_motif,'motif_concordant':str(ok).lower(),'new_repeat_bp_observed':c.repeat_bp_observed,
                'new_minus_frozen_bp':delta,'abs_new_minus_frozen_bp':ad,'materialization_mode':r.get('materialization_mode',''),**d})
out.parent.mkdir(parents=True,exist_ok=True); tmp=out.with_name('.'+out.name+'.part')
with tmp.open('w',newline='') as fh:
    wr=csv.DictWriter(fh,fieldnames=list(res[0]),delimiter='	'); wr.writeheader(); wr.writerows(res)
os.replace(tmp,out)
old_abs=[]
for r in old.values():
    try: old_abs.append(abs(float(r['new_minus_frozen_bp'])))
    except: pass
metrics=[
 ('fixture_rows',len(rows)),('caller_completed_rows',len(res)),('all_calls_overlap_prior',str(all(x>0 for x in overlaps)).lower()),
 ('motif_concordance_fraction',sum(motifok)/len(motifok)),('abs_new_minus_frozen_median_bp',statistics.median(absd)),
 ('abs_new_minus_frozen_p95_bp',percentile(absd,.95)),('abs_delta_gt50_rows',gt50),('abs_delta_gt100_rows',gt100),
 ('boundary_extension_gt50_rows',ext50),('context_limited_rows',context_limited),
 ('v0_2_abs_delta_median_bp',statistics.median(old_abs) if old_abs else '.'),('v0_2_abs_delta_p95_bp',percentile(old_abs,.95) if old_abs else '.'),
 ('comparison_semantics','SOFTWARE_REGRESSION_DESCRIPTIVE_NOT_BIOLOGICAL_TRUTH'),('regression_status','PASS_COMPLETION_AND_ANCHORING' if len(res)==60 and all(x>0 for x in overlaps) else 'FAIL')]
qc.parent.mkdir(parents=True,exist_ok=True); tmp=qc.with_name('.'+qc.name+'.part')
with tmp.open('w',newline='') as fh:
    wr=csv.writer(fh,delimiter='	'); wr.writerow(['metric','value']); wr.writerows(metrics)
os.replace(tmp,qc); print(qc.read_text(),end='')
if metrics[-1][1]!='PASS_COMPLETION_AND_ANCHORING': raise SystemExit(3)
PYREAL

python - "$BENCH/simple_periodic/synthetic_reference_selftest.qc.tsv"           "$BENCH/compound_interruption_lps/compound_interruption_lps_selftest.qc.tsv"           "$BENCH/boundary_censor_denovo/boundary_censor_denovo_selftest.qc.tsv"           "$BENCH/real_p01_regression.qc.tsv" "$STAGE_QC" "$CALLER" "$NOTE" <<'PYSTAGEQC'
import csv,sys,hashlib,os
from pathlib import Path

def q(p):
    with Path(p).open() as fh:return {r['metric']:r['value'].strip() for r in csv.DictReader(fh,delimiter='\t')}
def sha(p): return hashlib.sha256(Path(p).read_bytes()).hexdigest()
simple=q(sys.argv[1]); compound=q(sys.argv[2]); new=q(sys.argv[3]); real=q(sys.argv[4]); out=Path(sys.argv[5])
if simple.get('selftest_status')!='PASS': raise SystemExit('ERROR: simple periodic regression failed')
if compound.get('selftest_status')!='PASS': raise SystemExit('ERROR: compound/interruption/LPS regression failed')
if new.get('selftest_status')!='PASS': raise SystemExit('ERROR: boundary/censor/de-novo selftest failed')
if real.get('regression_status')!='PASS_COMPLETION_AND_ANCHORING': raise SystemExit('ERROR: real regression failed anchoring/completion')
rows=[
 ('stage_version','rnatr_general_repeat_caller_boundary_censor_denovo_v0.3.0'),('simple_periodic_regression','PASS'),
 ('simple_periodic_motif_accuracy',simple['catalog_prior_motif_accuracy']),('simple_periodic_length_abs_error_median_bp',simple['pure_uncensored_length_abs_error_median_bp']),('simple_periodic_length_abs_error_p95_bp',simple['pure_uncensored_length_abs_error_p95_bp']),
 ('compound_interruption_lps_regression','PASS'),('compound_specialized_fixture_pass_count',compound['fixture_pass_count']),
 ('boundary_censor_denovo_selftest','PASS'),('boundary_censor_denovo_fixture_pass_count',new['fixture_pass_count']),('max_denovo_period_tested',new['max_denovo_period_tested']),
 ('real_regression_rows',real['fixture_rows']),('real_regression_all_calls_overlap_prior',real['all_calls_overlap_prior']),('real_regression_motif_concordance_fraction',real['motif_concordance_fraction']),
 ('real_regression_abs_delta_median_bp',real['abs_new_minus_frozen_median_bp']),('real_regression_abs_delta_p95_bp',real['abs_new_minus_frozen_p95_bp']),('real_regression_abs_delta_gt50_rows',real['abs_delta_gt50_rows']),('real_regression_context_limited_rows',real['context_limited_rows']),
 ('boundary_semantics','PRIOR_ANCHORED_SOFT_EXTENSION'),('censored_semantics','EXPLICIT_GEOMETRY_LOWER_BOUND_NO_INVENTED_UPPER_BOUND'),('projection_window_semantics','CONTEXT_EDGE_NOT_BIOLOGICAL_CENSORING'),('denovo_semantics','CONDITIONAL_ANCHORED_RESCUE_PERIOD_1_TO_50'),
 ('real_regression_semantics','DESCRIPTIVE_SOFTWARE_REGRESSION_NOT_ACCURACY_THRESHOLD'),('performance_optimization','DEFERRED_UNTIL_DISEASE_SIM_BENCHMARK_SEMANTICS_STABLE'),
 ('caller_sha256',sha(sys.argv[6])),('implementation_note_sha256',sha(sys.argv[7])),('next_gate','DISEASE_LOCUS_AND_BROAD_SIMULATION_BENCHMARK'),('audit_status','PASS')]
out.parent.mkdir(parents=True,exist_ok=True); tmp=out.with_name('.'+out.name+'.part')
with tmp.open('w',newline='') as fh:
    wr=csv.writer(fh,delimiter='	'); wr.writerow(['metric','value']); wr.writerows(rows)
os.replace(tmp,out); print(out.read_text(),end='')
PYSTAGEQC

echo "===== SSOT UPDATE ====="
CLI_BAK="$SSOT_CLI.pre_stage12d.$(date +%Y%m%d_%H%M%S).bak"
DB_BAK="$SSOT_DB.pre_stage12d.$(date +%Y%m%d_%H%M%S).bak"
cp -a "$SSOT_CLI" "$CLI_BAK"; cp -a "$SSOT_DB" "$DB_BAK"
restore_ssot() { echo "ERROR: Stage 12D SSOT update failed; restoring backups" >&2; cp -a "$CLI_BAK" "$SSOT_CLI"; cp -a "$DB_BAK" "$SSOT_DB"; }
trap restore_ssot ERR

python - "$SSOT_CLI" <<'PYSSOT'
from pathlib import Path
import sys,py_compile,hashlib
cli=Path(sys.argv[1]); text=cli.read_text(encoding='utf-8')
marker='# Stage 12D boundary/censor/de-novo reference v0.3.0'
if marker in text:
    print('SSOT_STAGE12D_SOURCE_ALREADY_PATCHED'); raise SystemExit(0)
required=['# Stage 12B compound/interruption/LPS reference v0.2.0','def add_decision(','def add_interpretation(','def add_contract(','CREATE TABLE open_questions','CREATE TABLE limitations']
missing=[x for x in required if x not in text]
if missing: raise SystemExit('ERROR: SSOT structural preflight failed: '+', '.join(missing))
anchor='    current_metrics = [\n'
if text.count(anchor)!=1: raise SystemExit('ERROR: SSOT current_metrics anchor not unique')
insertion=r'''    # Stage 12D boundary/censor/de-novo reference v0.3.0
    general_ref_v03 = project_root / "src/rnatr_scout/general_caller/rnatr_general_repeat_caller_ref_v0.3.0.py"
    general_ref_v03_note = project_root / "docs/design/RNA_TR_Scout_general_repeat_caller_reference_v0.3.0.md"
    stage12d_qc = project_root / "qc/12_general_repeat_caller_boundary_censor_denovo/v0.3.0/general_repeat_caller_stage12d.qc.tsv"
    stage12c_qc = project_root / "qc/12_general_repeat_caller_real_regression_audit/v0.2.0/general_repeat_caller_real_regression_audit.qc.tsv"

    conn.execute("UPDATE open_questions SET status='OPEN', blocking=1, next_action='Reference v0.3.0 now implements prior-anchored soft boundaries, explicit geometry-based censored lower-bound semantics, projection-window context limitation, conditional de-novo/residual rescue through period 50, and alternative-motif score reporting. Next run disease-locus and broad simulation benchmarks before production optimization.', evidence_path=?, effective_at='2026-08-07T05:00:00+00:00' WHERE question_key='GENERAL_REPEAT_CALLER_IMPLEMENTATION'", (str(stage12d_qc),))
    conn.execute('INSERT OR REPLACE INTO limitations(limitation_key,statement,severity,status,mitigation,evidence_path,effective_at) VALUES(?,?,?,?,?,?,?)', ('PROJECTION_WINDOW_IS_NOT_MOLECULE_CENSORING','A projection-window edge is an analysis-context limit and must not be interpreted as biological/read censoring.','HIGH','ACTIVE','Use explicit evidence geometry for LEFT/RIGHT/BOTH censoring; report projection-window edge truncation separately as CONTEXT_LIMITED_LOWER_BOUND. Materialize full raw reads for later molecule-level validation when needed.',str(general_ref_v03_note),'2026-08-07T05:00:00+00:00'))
    add_decision(conn,key='general_repeat_caller_reference_v0_3_0',category='algorithm_design',title='General repeat caller reference v0.3.0 implemented',statement='Reference v0.3.0 anchors motif selection to the projected locus core before soft tract extension, separates explicit censoring from projection-window context limits, and uses conditional anchored de-novo rescue through period 50.',status='ACTIVE',confidence='MEDIUM',rationale='The 60-row real software-regression audit showed tract-boundary extension as the dominant discrepancy driver (21/60), motif-selection/de-novo differences in 11/60, and window-edge/context effects in 5/60. The contract change addresses those engineering failure modes without treating the frozen caller as biological truth.',evidence_path=str(stage12d_qc),effective_at='2026-08-07T05:00:00+00:00')
    add_interpretation(conn,key='real_p01_regression_driver_audit_stage12c',fact='In the 60-row real P0/P1 software-regression audit, likely drivers were tract-boundary extension 21, small difference 19, motif selection/de-novo 11, window edge/context 5, internal sizing semantics 3, and compound/interruption 1.',interpretation='The next reference caller should constrain motif/tract selection to remain locus-anchored and should distinguish artificial sequence-window limits from explicit molecule censoring.',do_not='Do not interpret these 60 rows as an accuracy estimate, biological distribution, normal range, or population technical floor.',confidence='HIGH',evidence_path=str(stage12c_qc),evidence_metrics={'tract_boundary_extension':21,'small_difference':19,'motif_selection_or_denovo':11,'window_edge_or_context':5,'internal_sizing_semantics':3,'compound_or_interruption':1},status='ACTIVE',effective_at='2026-08-07T05:00:00+00:00')
    add_contract(conn,key='repeat_definition',name='Repeat definition and sizing',state='REFERENCE_V0.3.0_PRE_BENCHMARK',statement='Reference v0.3.0 preserves raw-read cyclic measurement, compound/interruption segmentation and dual LPS, and adds prior-anchored soft boundary inference plus alternative-motif evidence. Disease/simulation benchmarking remains required before production freeze.',implementation_id=None,evidence_path=str(general_ref_v03_note))
    add_contract(conn,key='censoring_semantics',name='RNA repeat censoring and interval semantics',state='REFERENCE_IMPLEMENTED_V0.3.0',statement='SPAN may yield exact length when sequence context bounds the tract. LEFT/RIGHT/BOTH-censored molecules yield observed repeat lower bounds only with no invented finite upper bound. Projection-window edges are context limits, not biological censoring.',implementation_id=None,evidence_path=str(general_ref_v03_note))
    add_contract(conn,key='motif_hypothesis',name='Motif hypothesis and rescue semantics',state='REFERENCE_IMPLEMENTED_V0.3.0',statement='Catalog motif is the primary prior. De-novo/residual search through period 50 is conditionally activated only when catalog support in the projected core is inadequate, with primitive/rotation/reverse-complement collapse and alternative score reporting.',implementation_id=None,evidence_path=str(general_ref_v03_note))
'''
text=text.replace(anchor,insertion+anchor,1)
tmp=cli.with_name('.'+cli.name+'.stage12d.part'); tmp.write_text(text,encoding='utf-8'); py_compile.compile(str(tmp),doraise=True); tmp.replace(cli); cli.chmod(0o755)
print('SSOT_STAGE12D_SOURCE_PATCH_PASS'); print('ssot_cli_sha256	'+hashlib.sha256(cli.read_bytes()).hexdigest())
PYSSOT

python "$SSOT_CLI" --project-root "$PROJECT_ROOT" rebuild
python "$SSOT_CLI" --project-root "$PROJECT_ROOT" validate
trap - ERR

cat "$STAGE_QC"
echo "Caller: $CALLER"
echo "Bench:  $BENCH"
echo "QC:     $STAGE_QC"
echo "Note:   $NOTE"
echo "STAGE12D_PASS"
